class Solution {
    int M;
    unordered_map<int, int> mapping;
    mt19937 gen;
public:
    Solution(int n, vector<int>& blacklist) : M(n - (int)blacklist.size()), gen(random_device{}()) {
        unordered_set<int> black(blacklist.begin(), blacklist.end());
        int w = M;
        for (int b : blacklist) {
            if (b < M) {
                while (black.count(w)) w++;
                mapping[b] = w;
                w++;
            }
        }
    }

    int pick() {
        uniform_int_distribution<int> dist(0, M - 1);
        int r = dist(gen);
        auto it = mapping.find(r);
        if (it != mapping.end()) return it->second;
        return r;
    }
};
